CREATE TYPE "TaskStatus" AS ENUM ('PLANNED','IN_PROGRESS','BLOCKED','CODE_COMPLETE','TEST_FAILED','READY_FOR_REVIEW','VERIFIED','CANCELLED');
CREATE TYPE "Priority" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "DecisionStatus" AS ENUM ('PROPOSED','ACCEPTED','SUPERSEDED','REJECTED');
CREATE TYPE "SessionState" AS ENUM ('QUEUED','STARTING','RUNNING','WAITING_FOR_APPROVAL','SUCCEEDED','FAILED','CANCELLED','TIMED_OUT');
CREATE TYPE "EvidenceKind" AS ENUM ('CHANGED_FILES','GIT_DIFF','GIT_STATUS','TYPECHECK','LINT','UNIT_TEST','INTEGRATION_TEST','BUILD','MIGRATION','SCREENSHOT','ARTIFACT','COMMAND');
CREATE TYPE "Confidence" AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TYPE "ApprovalStatus" AS ENUM ('PENDING','APPROVED','REJECTED');

CREATE TABLE "Project" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"repositoryPath" TEXT NOT NULL UNIQUE,"defaultProvider" TEXT NOT NULL DEFAULT 'codex',"allowedCommands" JSONB NOT NULL,"permittedPaths" JSONB NOT NULL,"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Task" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"userRequest" TEXT NOT NULL,"objective" TEXT NOT NULL,"status" "TaskStatus" NOT NULL DEFAULT 'PLANNED',"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"relevantFiles" JSONB NOT NULL,"constraints" JSONB NOT NULL,"prohibitedChanges" JSONB NOT NULL,"assignedProvider" TEXT NOT NULL DEFAULT 'codex',"activeSessionId" TEXT,"parentTaskId" TEXT REFERENCES "Task"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AcceptanceCriterion" ("id" TEXT PRIMARY KEY,"taskId" TEXT NOT NULL REFERENCES "Task"("id") ON DELETE CASCADE,"description" TEXT NOT NULL,"passed" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Decision" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"context" TEXT NOT NULL,"decision" TEXT NOT NULL,"consequences" TEXT NOT NULL,"status" "DecisionStatus" NOT NULL DEFAULT 'PROPOSED',"locked" BOOLEAN NOT NULL DEFAULT false,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"supersededBy" TEXT,PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Decision_projectId_id_key" ON "Decision"("projectId","id");
CREATE TABLE "TaskCapsule" ("id" TEXT PRIMARY KEY,"taskId" TEXT NOT NULL REFERENCES "Task"("id") ON DELETE CASCADE,"content" JSONB NOT NULL,"approximateTokenCount" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AgentSession" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"taskId" TEXT NOT NULL REFERENCES "Task"("id") ON DELETE CASCADE,"providerId" TEXT NOT NULL,"state" "SessionState" NOT NULL DEFAULT 'QUEUED',"externalId" TEXT,"startedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),"exitCode" INTEGER,"error" TEXT,"usage" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AgentEvent" ("id" BIGSERIAL PRIMARY KEY,"sessionId" TEXT NOT NULL REFERENCES "AgentSession"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"stream" TEXT,"message" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AgentEvent_sessionId_id_idx" ON "AgentEvent"("sessionId","id");
CREATE TABLE "Evidence" ("id" TEXT PRIMARY KEY,"taskId" TEXT NOT NULL REFERENCES "Task"("id") ON DELETE CASCADE,"sessionId" TEXT REFERENCES "AgentSession"("id") ON DELETE SET NULL,"criterionId" TEXT REFERENCES "AcceptanceCriterion"("id") ON DELETE SET NULL,"kind" "EvidenceKind" NOT NULL,"commandId" TEXT,"startedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),"exitCode" INTEGER,"output" TEXT,"artifactPath" TEXT,"metadata" JSONB,"successful" BOOLEAN NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Checkpoint" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"reason" TEXT NOT NULL,"content" JSONB NOT NULL,"filePath" TEXT NOT NULL,"gitCommit" TEXT,"gitBranch" TEXT,"dirty" BOOLEAN NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MemoryUpdate" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"taskId" TEXT REFERENCES "Task"("id") ON DELETE SET NULL,"file" TEXT NOT NULL,"changed" TEXT NOT NULL,"reason" TEXT NOT NULL,"agent" TEXT NOT NULL,"evidenceRef" TEXT,"confidence" "Confidence" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Approval" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"action" TEXT NOT NULL,"rationale" TEXT NOT NULL,"status" "ApprovalStatus" NOT NULL DEFAULT 'PENDING',"decidedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditEvent" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"actor" TEXT NOT NULL,"action" TEXT NOT NULL,"details" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
